// Compile-time guard, no runtime code. `npm run check` fails here when the Drizzle schema
// (shared/schema.ts) and the migrated database (shared/database.types.ts, generated by
// `npm run db:types`) disagree about a table's columns, types or nullability.
import type { Database } from "./database.types";
import type {
  AdminUser,
  ChipStructure,
  NotificationSubscriber,
  Registration,
  Tournament,
  TournamentResult,
  TournamentRules,
} from "./schema";

type Tables = Database["public"]["Tables"];

type SnakeCase<S extends string> = S extends `${infer Head}${infer Tail}`
  ? `${Head extends Lowercase<Head> ? Head : `_${Lowercase<Head>}`}${SnakeCase<Tail>}`
  : S;

// Express a Drizzle row the way the generated types do: snake_case column names (Drizzle
// exposes camelCase properties) and `string` timestamps (Drizzle's `timestamp()` yields `Date`).
type AsDbRow<T> = {
  [K in keyof T as SnakeCase<K & string>]: T[K] extends Date ? string : T[K];
};

type Same<A, B> = [A] extends [B] ? ([B] extends [A] ? true : false) : false;
type Expect<T extends true> = T;

export type SchemaMatchesDatabase = [
  Expect<Same<AsDbRow<Tournament>, Tables["tournaments"]["Row"]>>,
  Expect<Same<AsDbRow<Registration>, Tables["registrations"]["Row"]>>,
  Expect<Same<AsDbRow<TournamentResult>, Tables["tournament_results"]["Row"]>>,
  Expect<Same<AsDbRow<NotificationSubscriber>, Tables["notification_subscribers"]["Row"]>>,
  Expect<Same<AsDbRow<AdminUser>, Tables["admin_users"]["Row"]>>,
  Expect<Same<AsDbRow<TournamentRules>, Tables["tournament_rules"]["Row"]>>,
  Expect<Same<AsDbRow<ChipStructure>, Tables["chip_structure"]["Row"]>>,
];
